const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 400;

let player = {x: 100, y: canvas.height-50, w: 30, h:30, vy:0, onGround:false};

const keys = {};
document.addEventListener('keydown', e=>keys[e.key]=true);
document.addEventListener('keyup', e=>keys[e.key]=false);

let barriers = [];
let frame = 0;
let speed = 2;

function spawnBarrier() {
  const gapHeight = 80;
  const barHeight = Math.random()*200+50;
  const gapY = Math.random()*(canvas.height-gapHeight);
  barriers.push({x: canvas.width, y:0, w:30, h:gapY});
  barriers.push({x: canvas.width, y:gapY+gapHeight, w:30, h:canvas.height-(gapY+gapHeight)});
}

function update() {
  // player input
  if ((keys['ArrowLeft']||keys['a']) && player.x>0) player.x -= 4;
  if ((keys['ArrowRight']||keys['d']) && player.x+player.w<canvas.width) player.x += 4;
  if ((keys['ArrowUp']||keys['w']||keys[' ']) && player.onGround) { player.vy = -8; player.onGround = false; }

  // gravity
  player.vy += 0.4;
  player.y += player.vy;
  if (player.y + player.h >= canvas.height) {
    player.y = canvas.height - player.h;
    player.vy = 0;
    player.onGround = true;
  }

  // barriers
  if (frame % 120 === 0) spawnBarrier();
  barriers.forEach(b=> b.x -= speed);
  barriers = barriers.filter(b=> b.x + b.w > 0);

  // collision
  for (let b of barriers) {
    if (player.x < b.x + b.w && player.x + player.w > b.x &&
        player.y < b.y + b.h && player.y + player.h > b.y) {
      // lose
      cancelAnimationFrame(anim);
      alert('Game Over');
      return;
    }
  }

  // draw
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.fillStyle = '#0ff';
  ctx.fillRect(player.x, player.y, player.w, player.h);
  ctx.fillStyle = '#f0f';
  barriers.forEach(b=> {
    ctx.fillRect(b.x, b.y, b.w, b.h);
  });

  frame++;
  anim = requestAnimationFrame(update);
}
let anim = requestAnimationFrame(update);
```

